package com.bank.checkpoint.core;

import java.util.*;
import java.util.logging.Logger;

// Models reliable, replicated storage (HDFS/S3) for checkpoints.
public class ReliableStore {
    private static final Logger log = Logger.getLogger(ReliableStore.class.getName());
    private final Map<String, Long> files = new HashMap<>(); // name -> value

    public void write(String name, long value) {
        files.put(name, value);
        log.info(() -> "CHECKPOINT written to reliable store: " + name + "=" + value);
    }
    public boolean exists(String name) { return files.containsKey(name); }
    public long read(String name) { return files.get(name); }
}
