package com.bank.checkpoint.core;

import java.util.logging.Logger;

// A dataset whose lineage grows each iteration; supports cache + checkpoint.
public class IterativeDataset {
    private static final Logger log = Logger.getLogger(IterativeDataset.class.getName());

    private long value;              // the current computed value
    private int lineageDepth = 0;    // grows each transformation
    private boolean cached = false;  // cache: stored on executors, lineage KEPT
    private String checkpointName;   // set when checkpointed
    private final ReliableStore store;

    public IterativeDataset(long seed, ReliableStore store) {
        this.value = seed;
        this.store = store;
    }

    // A transformation: extends lineage (imagine one iteration of a loop).
    public IterativeDataset iterate() {
        value = value + value / 10;   // some iterative update
        lineageDepth++;
        return this;
    }

    public int getLineageDepth() { return lineageDepth; }
    public long getValue() { return value; }

    // CACHE: store on executors, PRESERVE lineage (fast reuse, not durable).
    public IterativeDataset cache() {
        cached = true;
        log.info(() -> "cache(): stored on executors, lineage PRESERVED (depth="
                + lineageDepth + "), not durable");
        return this;
    }

    // CHECKPOINT: write to reliable store, TRUNCATE lineage (durable).
    public IterativeDataset checkpoint(String name) {
        if (!cached) {
            log.warning("checkpoint without cache → recompute full lineage to write it");
        } else {
            log.info("checkpoint reads from CACHE (no full recompute) — cache-then-checkpoint");
        }
        store.write(name, value);
        this.checkpointName = name;
        this.lineageDepth = 0;       // lineage TRUNCATED
        log.info(() -> "checkpoint(): lineage TRUNCATED to depth=0 (reliable copy is new source)");
        return this;
    }

    // Recover after a failure: cache lost → from lineage; checkpoint → from reliable store.
    public long recover() {
        if (checkpointName != null && store.exists(checkpointName)) {
            long v = store.read(checkpointName);
            log.info(() -> "recover from CHECKPOINT (reliable store), depth=0, value=" + v);
            return v;
        }
        log.warning(() -> "no checkpoint → recompute from lineage depth=" + lineageDepth);
        return value;
    }
}
