package com.bank.checkpoint;

import com.bank.checkpoint.core.*;
import java.util.logging.*;

public class CheckpointDemo {
    private static final Logger log = Logger.getLogger(CheckpointDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new CheckpointLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        ReliableStore store = new ReliableStore();
        // Seed with Rajesh's opening aggregate.
        IterativeDataset ds = new IterativeDataset(1_000_000, store);

        // Run 50 iterations → lineage grows to 50 (risk-model style loop).
        for (int i = 0; i < 50; i++) ds.iterate();
        log.info(() -> "after 50 iterations: lineage depth=" + ds.getLineageDepth()
                + ", value=" + ds.getValue());

        // Cache for reuse (lineage preserved), then checkpoint (lineage truncated).
        ds.cache().checkpoint("risk_model_iter50");

        // Continue iterating — lineage grows from 0 again, bounded.
        for (int i = 0; i < 10; i++) ds.iterate();
        log.info(() -> "after 10 more: lineage depth=" + ds.getLineageDepth()
                + " (bounded thanks to checkpoint)");

        // Simulate failure → recover from the reliable checkpoint.
        log.info(() -> "recovered value = " + ds.recover());
    }
}

